# Avoid opening clauses that depend on a previous verse and fragments ending in a colon.
BAD_START=re.compile(r"^(?:and|but|for|therefore|wherefore|because|so that|which|who|whose|whom|that|then|or|nevertheless|moreover|now when|as it is written|saying|unto whom|to whom|in whom|of whom|wherein|whereby|even as|if|when|while|after|before|until|except|lest|behold,? and)\\b",re.I)
BAD_AR=re.compile(r"^(?:وَ?لَكِنْ|لأَنَّ|لِكَيْ|حَتَّى|إِذْ|وَإِذْ|فَلَمَّا|وَلَمَّا|قَائِلًا|قَائِلِينَ)")
AR_DIGITS=str.maketrans("0123456789","٠١٢٣٤٥٦٧٨٩")
def load(lang,version,book):
 url=f"{BASE}/{lang}/{version}/books/{book}.json"
 req=urllib.request.Request(url,headers={"User-Agent":"VelthonBibleTV/1.4 public-domain-data"})
 with urllib.request.urlopen(req,timeout=45) as f:return json.load(f)
def flatten(book):
 return {(chapter["chapter"],v["number"]):v["text"] for chapter in book["chapters"] for v in chapter["verses"]}
def main():
 result=[]
 for book in BOOKS:
  a=flatten(load("ar","svd",book));e=flatten(load("en","kjv",book))
  for (ch,num),ar in a.items():
   en=e.get((ch,num))
   if (num in SELECTED.get(book,{}).get(ch,[]) and en
       and 20<=len(ar)<=300 and 18<=len(en)<=330
       and not BAD_START.search(en.strip()) and not BAD_AR.search(ar.strip())
       and not en.rstrip().endswith((':',';',',')) and not ar.rstrip().endswith(('،','؛',':'))):
    arabic_book,english_book=NAMES[book]
    result.append({"ar":ar.strip(),"en":en.strip(),"ref":f"{book} {ch}:{num}","ref_ar":f"{arabic_book} {ch}:{num}".translate(AR_DIGITS),"ref_en":f"{english_book} {ch}:{num}"})
 if len(result)<250:raise RuntimeError("Only "+str(len(result))+" curated standalone verses; at least 250 required for one-hour nonrepeat at 15 seconds")
 target=pathlib.Path("app/src/main/assets/bible_verses.json")
 target.parent.mkdir(parents=True,exist_ok=True)
 target.write_text(json.dumps(result,ensure_ascii=False),encoding="utf-8")
 print("Bundled",len(result),"curated, standalone, bilingual public-domain Bible verses, bytes:",target.stat().st_size)
if __name__=="__main__":main()
